// Package textconv provides helpers for converting text between character
// encodings and applying Unicode normalization forms.
package textconv

import (
	"fmt"

	"golang.org/x/text/encoding"
	"golang.org/x/text/encoding/ianaindex"
	"golang.org/x/text/transform"
	"golang.org/x/text/unicode/norm"
)

// lookup resolves an encoding by its IANA name (for example "windows-1252",
// "shift_jis" or "GBK"). A nil encoding is returned for UTF-8, which is the
// assumed internal representation and therefore needs no conversion.
func lookup(name string) (*encoding.Encoding, error) {
	enc, err := ianaindex.IANA.Encoding(name)
	if err != nil {
		return nil, fmt.Errorf("textconv: unknown encoding %q: %w", name, err)
	}
	return enc, nil
}

// Decode converts src from the named character encoding to UTF-8.
func Decode(name string, src []byte) ([]byte, error) {
	enc, err := lookup(name)
	if err != nil {
		return nil, err
	}
	if enc == nil {
		return append([]byte(nil), src...), nil
	}
	out, _, err := transform.Bytes((*enc).NewDecoder(), src)
	if err != nil {
		return nil, fmt.Errorf("textconv: decode %q: %w", name, err)
	}
	return out, nil
}

// Encode converts UTF-8 src to the named character encoding.
func Encode(name string, src []byte) ([]byte, error) {
	enc, err := lookup(name)
	if err != nil {
		return nil, err
	}
	if enc == nil {
		return append([]byte(nil), src...), nil
	}
	out, _, err := transform.Bytes((*enc).NewEncoder(), src)
	if err != nil {
		return nil, fmt.Errorf("textconv: encode %q: %w", name, err)
	}
	return out, nil
}

// Normalize returns s in the requested Unicode normalization form.
func Normalize(form norm.Form, s string) string {
	return form.String(s)
}

// IsNormal reports whether s is already in the requested normalization form.
func IsNormal(form norm.Form, s string) bool {
	return form.IsNormalString(s)
}

package textconv

import (
	"testing"

	"golang.org/x/text/unicode/norm"
)

func TestDecodeWindows1252(t *testing.T) {
	// "Café" encoded as windows-1252 (0xE9 is é).
	src := []byte{0x43, 0x61, 0x66, 0xE9}
	got, err := Decode("windows-1252", src)
	if err != nil {
		t.Fatalf("Decode: %v", err)
	}
	if want := "Café"; string(got) != want {
		t.Fatalf("Decode = %q, want %q", got, want)
	}
}

func TestEncodeRoundTrip(t *testing.T) {
	want := []byte{0x43, 0x61, 0x66, 0xE9}
	enc, err := Encode("windows-1252", []byte("Café"))
	if err != nil {
		t.Fatalf("Encode: %v", err)
	}
	if string(enc) != string(want) {
		t.Fatalf("Encode = % x, want % x", enc, want)
	}
}

func TestDecodeUnknownEncoding(t *testing.T) {
	if _, err := Decode("not-a-real-encoding", []byte("x")); err == nil {
		t.Fatal("Decode: expected error for unknown encoding")
	}
}

func TestNormalize(t *testing.T) {
	// U+00E9 (é) decomposed is U+0065 U+0301 (e + combining acute).
	decomposed := "e\u0301"
	if IsNormal(norm.NFC, decomposed) {
		t.Fatal("decomposed string unexpectedly reports as NFC")
	}
	composed := Normalize(norm.NFC, decomposed)
	if composed != "\u00e9" {
		t.Fatalf("Normalize(NFC) = %q, want %q", composed, "\u00e9")
	}
	if !IsNormal(norm.NFC, composed) {
		t.Fatal("composed string should report as NFC")
	}
}

package main

import (
	"fmt"
	"os"

	"textconv/internal/textconv"

	"golang.org/x/text/unicode/norm"
)

func main() {
	if err := run(); err != nil {
		fmt.Fprintln(os.Stderr, "error:", err)
		os.Exit(1)
	}
}

func run() error {
	// "Café" in windows-1252.
	src := []byte{0x43, 0x61, 0x66, 0xE9}

	utf8, err := textconv.Decode("windows-1252", src)
	if err != nil {
		return err
	}

	// Normalize to NFC so combining marks are composed.
	nfc := textconv.Normalize(norm.NFC, string(utf8))

	fmt.Printf("decoded: %s\n", utf8)
	fmt.Printf("nfc:     %s\n", nfc)

	back, err := textconv.Encode("windows-1252", []byte(nfc))
	if err != nil {
		return err
	}
	fmt.Printf("encoded: % x\n", back)
	return nil
}

